"""Algorithm 1: Fermat-pair embedding and Berggren address extraction.

Given an odd N = p*q with 1 < p < q coprime, compute its node in the tree of primitive
Pythagorean triples and the unique word in {A, B, C} that reaches it from the root (2,1),
by repeatedly applying the parent-interval law.  The reconstruction map (evaluating the word
back to the node) is included as a self-check.
"""

from __future__ import annotations

from typing import List, Tuple

Pair = Tuple[int, int]
ROOT: Pair = (2, 1)


def fermat_pair(p: int, q: int) -> Pair:
    """The node of N = p*q: ((q+p)/2, (q-p)/2), so that m^2 - n^2 = N."""
    if p % 2 == 0 or q % 2 == 0 or not 1 < p < q:
        raise ValueError("need odd coprime factors with 1 < p < q")
    return ((q + p) // 2, (q - p) // 2)


def letter_of(node: Pair) -> str:
    """Branch letter, decided by the band of the ratio m/n (the parent-interval law)."""
    m, n = node
    if m < 2 * n:
        return "A"
    if m < 3 * n:
        return "B"
    return "C"


def parent_pair(node: Pair) -> Pair:
    """The unique Berggren parent, decided by the same band."""
    m, n = node
    if m < 2 * n:
        return (n, 2 * n - m)
    if m < 3 * n:
        return (n, m - 2 * n)
    return (m - 2 * n, n)


def apply_gen(letter: str, node: Pair) -> Pair:
    """Child maps: A(m,n) = (2m-n, m), B(m,n) = (2m+n, m), C(m,n) = (m+2n, n)."""
    m, n = node
    return {"A": (2 * m - n, m), "B": (2 * m + n, m), "C": (m + 2 * n, n)}[letter]


def address(node: Pair, cap: int = 10 ** 7) -> List[str]:
    """The address of a node, read from the node upward to the root.

    Each step strictly decreases m + n by at least 2, so the loop terminates after at most
    (m + n - 3) / 2 iterations; `cap` merely guards against malformed input.
    """
    word: List[str] = []
    cur = node
    while cur != ROOT:
        if len(word) >= cap:
            raise RuntimeError("cap exceeded: input was probably not a valid node")
        word.append(letter_of(cur))
        cur = parent_pair(cur)
    return word


def eval_word(word: List[str]) -> Pair:
    """Evaluate an address back to its node: the inverse of `address`."""
    cur = ROOT
    for letter in reversed(word):
        cur = apply_gen(letter, cur)
    return cur


def factor_from_address(word: List[str]) -> Tuple[int, int]:
    """Knowing the address is knowing the factorisation: p = m - n, q = m + n."""
    m, n = eval_word(word)
    return (m - n, m + n)


if __name__ == "__main__":
    p, q = 1009, 4001
    node = fermat_pair(p, q)
    word = address(node)
    assert eval_word(word) == node
    assert factor_from_address(word) == (p, q)
    print(f"N = {p*q}, node = {node}, depth = {len(word)}")
    print(f"first letter = {word[0]}  (balance band: q/p = {q/p:.3f})")
    print(f"recovered factors from the address: {factor_from_address(word)}")

"""Algorithm 2: constructive seal-witness generator.

For a modulus M and a depth t, emit three genuine tree nodes whose values N are congruent
modulo M, whose addresses agree in every letter shallower than t, and whose letters at depth t
are A, B and C.  Their existence is a proof that no function of (N mod M, shallower prefix)
can output the letter at depth t.

Two families are produced:

  * the *proper* first-letter family, valid for every M >= 2 (odd or even) and giving
    nontrivial factorisations,

        W_A = (4M-1, 2M)   N = (2M-1)(6M-1)
        W_B = (4M+1, 2M)   N = (2M+1)(6M+1)
        W_C = (6M+1, 2M)   N = (4M+1)(8M+1),

  * the *positionwise* family, valid for every M >= 2 and every depth t,

        nu(M,k,t) = (4tM + 2Mk + 1, 2M),   k = 1, 2, 3.

All arithmetic is exact integer arithmetic; the generator is O(t) per witness (the descent
used only to verify the prefix) and O(1) to emit.
"""

from __future__ import annotations

from math import gcd
from typing import Dict, List, Tuple

Pair = Tuple[int, int]


def n_of(node: Pair) -> int:
    m, n = node
    return m * m - n * n


def is_node(node: Pair) -> bool:
    """0 < n < m, coprime, opposite parity."""
    m, n = node
    return 0 < n < m and gcd(m, n) == 1 and (m + n) % 2 == 1


def letter_of(node: Pair) -> str:
    m, n = node
    return "A" if m < 2 * n else ("B" if m < 3 * n else "C")


def parent_pair(node: Pair) -> Pair:
    m, n = node
    if m < 2 * n:
        return (n, 2 * n - m)
    if m < 3 * n:
        return (n, m - 2 * n)
    return (m - 2 * n, n)


def letter_at(t: int, node: Pair) -> str:
    cur = node
    for _ in range(t):
        cur = parent_pair(cur)
    return letter_of(cur)


def proper_witnesses(M: int) -> Dict[str, Pair]:
    """Three first-letter witnesses in the class N = 1 (mod M), with nontrivial factors."""
    if M < 2:
        raise ValueError("need M >= 2")
    return {"A": (4 * M - 1, 2 * M), "B": (4 * M + 1, 2 * M), "C": (6 * M + 1, 2 * M)}


def depth_witnesses(M: int, t: int) -> Dict[str, Pair]:
    """Three witnesses whose letters at depth t are A, B, C, with identical shallower prefix."""
    if M < 2 or t < 0:
        raise ValueError("need M >= 2 and t >= 0")
    return {lab: (4 * t * M + 2 * M * k + 1, 2 * M)
            for lab, k in (("A", 1), ("B", 2), ("C", 3))}


def verify(M: int, t: int) -> List[str]:
    """Check every claim about both families and return a human-readable report."""
    report: List[str] = []

    fam = proper_witnesses(M)
    residues = {n_of(v) % M for v in fam.values()}
    assert len(residues) == 1
    for lab, v in fam.items():
        assert is_node(v), f"{v} is not a tree node"
        assert letter_of(v) == lab
        assert v[0] - v[1] >= 2 * M - 1 >= 3, "factorisation must be nontrivial"
    report.append(f"first-letter family at M={M}: letters A,B,C all with "
                  f"N = {residues.pop()} (mod {M}), factors >= {2*M-1}")

    dep = depth_witnesses(M, t)
    residues = {n_of(v) % M for v in dep.values()}
    assert len(residues) == 1
    for lab, v in dep.items():
        assert is_node(v)
        assert all(letter_at(s, v) == "C" for s in range(t)), "prefixes must agree"
        assert letter_at(t, v) == lab
    report.append(f"depth-{t} family at M={M}: identical prefix C^{t}, letters A,B,C at "
                  f"depth {t}, all with N = {residues.pop()} (mod {M})")
    return report


if __name__ == "__main__":
    for M in (2, 3, 9, 27, 100, 2 ** 20 + 1):
        for t in (0, 3, 7):
            for line in verify(M, t):
                print(line)
